// Environment Admin is a built-in platform role with a fixed, global ID across
// every PingOne tenant. Referencing it directly in canBeAssignedBy avoids a
// separate GET /roles lookup — which an Environment Admin worker cannot perform
// anyway, since listing platform roles requires Organization Admin.
// See: https://apidocs.pingidentity.com/pingone/platform/v1/api/#built-in-admin-roles
const ENV_ADMIN_ROLE_ID = '29ddce68-cd7f-4b2a-b6fc-f7a19553b496';

// --- Workflow ---

/**
 * runWorkflow executes the full custom admin role lifecycle and returns
 * { success, steps[] }. Each step is a plain object matching the StepResult
 * shape. On failure the function returns immediately, leaving steps populated
 * up to and including the failed step so the UI can highlight the problem.
 */
async function runWorkflow() {
  const steps = [];

  // Step 1: obtain a bearer token via client_credentials.
  // The worker app must hold Environment Admin — without it, later calls
  // to create custom roles or assign them will return 403 Forbidden.
  let token;
  try {
    token = await getAdminToken();
  } catch (err) {
    steps.push({ title: 'Obtain admin access token', ok: false, detail: err.message });
    return { success: false, steps };
  }
  steps.push({ title: 'Obtain admin access token', ok: true, detail: 'client_credentials grant succeeded.' });

